 function nextTouch(g){var dates=[];g.contacts.forEach(function(c){if(c.nextTouch&&c.nextTouch>=now())dates.push(c.nextTouch)});g.tasks.forEach(function(t){if(t.status!=='completed'&&t.dueDate&&t.dueDate>=now())dates.push(t.dueDate)});g.openOpps.forEach(function(o){if(o.nextDate&&o.nextDate>=now())dates.push(o.nextDate)});return dates.sort(function(a,b){return a-b})[0]||null}
