   for(var i=1;i<dates.length;i++){var gap=days(dates[i-1],dates[i]);if(gap!=null&&gap>0)gaps.push(gap)}
   r.ordersList=orders;r.lastDate=dates.length?dt(dates[dates.length-1]):null;r.firstDate=dates.length?dt(dates[0]):null;
