 function categoryPurchased(rows,idea){
  var nidea=norm(idea);
  return rows.some(function(r){
   var c=norm(r.category+' '+r.subcategory+' '+r.name);
   if(/safety|hi vis/.test(nidea))return /safety|hi vis|high visibility|reflect/.test(c);
   if(/outerwear/.test(nidea))return /jacket|outerwear|vest|coat|fleece/.test(c);
   if(/headwear/.test(nidea))return /hat|cap|headwear|beanie/.test(c);
   if(/workwear/.test(nidea))return /workwear|pant|work shirt|uniform|duck/.test(c);
   if(/drinkware/.test(nidea))return /drink|tumbler|bottle|mug|cup/.test(c);
   if(/t shirts/.test(nidea))return /t shirt|tee/.test(c);
   return c.indexOf(nidea)>=0
  })
 }
 function reorderStatusLabel(p){
  if(p.reorderStatus==='overdue')return{label:'Past forecast',tone:'risk',copy:Math.abs(p.forecastGap)+' days past the directional date'};
  if(p.reorderStatus==='due')return{label:'Review now',tone:'warn',copy:p.forecastGap<0?Math.abs(p.forecastGap)+' days past forecast':'Forecast in '+p.forecastGap+' days'};
  if(p.reorderStatus==='upcoming')return{label:'Upcoming',tone:'info',copy:'Forecast in '+p.forecastGap+' days'};
  if(p.reorderStatus==='later')return{label:'Later',tone:'good',copy:'Forecast in '+p.forecastGap+' days'};
  return{label:'Not enough history',tone:'info',copy:'A cadence forecast requires repeat dated purchases'}
 }
