 window._cw4SaveContact=function(encoded){var name=resolveOpenName(),b=account(name,true),idv=encoded?decodeURIComponent(encoded):'',idx=b.data.contacts.findIndex(function(c){return c&&String(c.id)===idv}),stamp=new Date().toISOString(),c={id:idv||id('ct'),source:'local',name:val('cw4-f-name')||'Unnamed contact',title:val('cw4-f-title'),email:val('cw4-f-email'),phone:val('cw4-f-phone2'),buyingRole:val('cw4-f-role')||'Unknown',preferredChannel:val('cw4-f-channel'),isPrimary:val('cw4-f-primary')==='Yes',decisionMaker:val('cw4-f-decision')==='Yes',lastTouch:val('cw4-f-last'),nextTouch:val('cw4-f-next'),notes:val('cw4-f-notes'),createdAt:idx>=0?b.data.contacts[idx].createdAt||stamp:stamp,updatedAt:stamp};if(c.isPrimary)b.data.contacts.forEach(function(x){if(x)x.isPrimary=false});if(idx>=0)b.data.contacts[idx]=Object.assign({},b.data.contacts[idx],c);else b.data.contacts.push(c);saveAccount(b);audit(idx>=0?'Contact updated':'Contact created',c.name,name);window._cw4Modal=null;render()};
 window._cw4SaveActivity=function(){var name=resolveOpenName(),b=account(name,true),raw=val('cw4-f-contact'),parts=raw.split('|'),contactId=parts[0]||'',contactName=parts.slice(1).join('|'),stamp=new Date().toISOString(),a={id:id('act'),source:'local',type:val('cw4-f-type')||'Activity',date:val('cw4-f-date')||iso(now()),contactId:contactId,contactName:contactName,subject:val('cw4-f-subject')||'Customer activity',detail:val('cw4-f-detail'),outcome:val('cw4-f-outcome'),nextStep:val('cw4-f-nextaction'),nextDate:val('cw4-f-nextdate'),createdAt:stamp,updatedAt:stamp};b.data.activities.push(a);if(contactId){var i=b.data.contacts.findIndex(function(c){return c&&String(c.id)===contactId});if(i>=0){b.data.contacts[i].lastTouch=a.date;if(a.nextDate)b.data.contacts[i].nextTouch=a.nextDate;b.data.contacts[i].updatedAt=stamp}}saveAccount(b);audit('Activity logged',a.subject,name+' · '+a.type);window._cw4Modal=null;render()};
 window._cw4SaveTask=function(){var name=resolveOpenName(),s=read(ACTION);if(!s||s.version!==1||!s.reps)s={version:1,reps:{}};s.reps[_rp2.rep]=s.reps[_rp2.rep]||{manual:[],state:{},events:[]};var d=s.reps[_rp2.rep];d.manual=arr(d.manual);d.state=d.state||{};d.events=arr(d.events);var due=val('cw4-f-due'),key='cw4:'+norm(name)+':'+norm(val('cw4-f-task'))+':'+due,duplicate=d.manual.some(function(t){var st=d.state[t.id]||{};return t&&t.customerWorkspaceKey===key&&st.status!=='completed'});if(!duplicate){var t={id:id('manual'),source:'manual',category:'customer',tone:'info',score:160,title:val('cw4-f-task')||('Follow up with '+name),why:val('cw4-f-why'),action:val('cw4-f-action'),measure:val('cw4-f-measure'),dueDate:due,customer:name,customerWorkspaceKey:key,page:'customers'};d.manual.push(t);d.events.push({type:'create',taskId:t.id,title:t.title,customer:name,at:new Date().toISOString()});localStorage.setItem(ACTION,JSON.stringify(s));audit('Customer task created',t.title,name+' · '+due)}invalidateCustomerWorkspace();window._cw4Modal=null;render()};
 window._cw4SaveOpportunity=function(){var name=resolveOpenName(),b=account(name,true),stamp=new Date().toISOString(),o={id:id('opp'),source:'local',title:val('cw4-f-oppname')||'Customer opportunity',stage:val('cw4-f-stage')||'Discovery',amount:n(val('cw4-f-value')),probability:Math.max(0,Math.min(100,n(val('cw4-f-prob')))),expectedClose:val('cw4-f-close'),nextStepDate:val('cw4-f-oppdate'),customerNeed:val('cw4-f-need'),products:val('cw4-f-products'),nextStep:val('cw4-f-oppnext'),createdAt:stamp,updatedAt:stamp,history:[{type:'Opportunity created',copy:'Created from Customer Workspace 5.0',at:stamp}]};b.data.opportunities.push(o);saveAccount(b);audit('Opportunity created',o.title,name+' · '+money(o.amount));window._cw4Modal=null;render()};
